#!/usr/bin/env bash
set -Eeuo pipefail
EXPECTED='6ec732645b0a6047d13adfa8b1f236990bfb2a6dc193bbe1d57322cfd0600e86'
PAYLOAD_B64=''
TMP="$(mktemp /tmp/zdt-v19-compact-builder.XXXXXX.js)"
trap 'rm -f "$TMP"' EXIT
printf '%s' "$PAYLOAD_B64" | base64 -d | gzip -d > "$TMP"
ACTUAL="$(sha256sum "$TMP" | awk '{print $1}')"
test "$ACTUAL" = "$EXPECTED"
exec /usr/local/bin/prhm-node "$TMP" "$@"
